namespace {
QString runsDirectory(){return QStandardPaths::writableLocation(QStandardPaths::AppDataLocation)+"/playground/runs";}
QString newRunPath(const QString &root){return QDir(root).filePath(QDateTime::currentDateTimeUtc().toString("yyyyMMdd-HHmmss-zzz"));}
QJsonObject readObject(const QString &path,QString &error){QFile file(path);if(!file.open(QIODevice::ReadOnly)){error=QObject::tr("Nie można odczytać pliku.");return {};}QJsonParseError parse;const auto doc=QJsonDocument::fromJson(file.readAll(),&parse);if(parse.error!=QJsonParseError::NoError || !doc.isObject()){error=QObject::tr("Nieprawidłowy plik JSON.");return {};}error.clear();return doc.object();}
}
PlaygroundController::PlaygroundController(QObject *parent):QObject(parent),m_config(Playground::example()) {
    m_athletePacks.append(tr("Stawka syntetyczna"));m_rosters.append(QJsonObject());m_hillNames.append(tr("Skocznia syntetyczna"));m_hills.append(QJsonObject());m_ruleNames.append(tr("Zasady eksperymentu"));m_rules.append(QJsonObject());
    auto *database=GlobalDatabase::get();
    for(const auto &pack:database->getPacks())if(pack.kind==DataPack::Jumpers && pack.jumpers.size()>=2 && pack.jumpers.size()<=512){QJsonArray roster;for(const auto &athlete:pack.jumpers)roster.append(Jumper::getJsonObject(athlete));m_athletePacks.append(pack.name);m_rosters.append(QJsonObject{{"roster",roster}});}
    for(const auto &hill:database->getEditableGlobalHills())if(hill.getKPoint()>=10 && hill.getHSPoint()>=hill.getKPoint()){m_hillNames.append(hill.getName()+" HS"+QString::number(hill.getHSPoint()));m_hills.append(Hill::getJsonObject(hill));}
    for(const auto &rules:database->getEditableCompetitionRules())if(!rules.getRounds().isEmpty()){m_ruleNames.append(rules.getName());m_rules.append(CompetitionRules::getJsonObject(rules));}
    const auto settings=GlobalSimulationSettings::snapshot();auto parameters=m_config["parameters"].toObject();parameters["engine.dsq"]=settings.baseDsqProbability;parameters["engine.maxSkills"]=settings.maxSkills;parameters["engine.autoHillEffects"]=settings.autoAdjustHillEffects?1:0;parameters["engine.randomness"]=settings.simulationRandomMultiplier;parameters["engine.takeoffForm"]=settings.takeoffFormEffect;parameters["engine.flightForm"]=settings.flightFormEffect;parameters["engine.hillEffects"]=settings.hillsEffectsMultiplier;m_config["parameters"]=parameters;
    m_progress.setInterval(100);connect(&m_progress,&QTimer::timeout,this,&PlaygroundController::progressChanged);
    connect(&m_watcher,&QFutureWatcher<QJsonObject>::finished,this,[this]{m_progress.stop();const auto result=m_watcher.result();setProperty("playgroundPendingRun",false);if(result.contains("error")){setMessage(result["error"].toString());emit progressChanged();return;}m_report=result;m_reportMap=result.toVariantMap();m_replay={};m_replayMap.clear();QString error;const auto path=newRunPath(runsDirectory());if(Playground::exportReport(result,path,error)){setMessage(result["canceled"].toBool()?tr("Przerwano. Zachowano %1 pełnych porównań.").arg(result["completed"].toInt()):tr("Zakończono %1 porównań. Wyniki zapisano w historii.").arg(result["completed"].toInt()));refreshHistory();}else setMessage(tr("Wyniki są dostępne; zapis historii nie powiódł się: %1").arg(error));emit reportChanged();emit progressChanged();});
    connect(&m_replayWatcher,&QFutureWatcher<QJsonObject>::finished,this,[this]{m_progress.stop();const auto result=m_replayWatcher.result();if(result.contains("error"))setMessage(result["error"].toString());else {m_replay=result;m_replayMap=result.toVariantMap();setMessage(tr("Odtworzono konkurs %1.").arg(result["competition"].toInt()+1));emit replayChanged();}emit progressChanged();});refreshHistory();
}
PlaygroundController::~PlaygroundController(){if(m_control)m_control->canceled.store(true,std::memory_order_relaxed);m_watcher.waitForFinished();m_replayWatcher.waitForFinished();if(property("playgroundPendingRun").toBool()){const auto result=m_watcher.result();if(!result.contains("error")){QString error;if(!Playground::exportReport(result,newRunPath(runsDirectory()),error))qWarning().noquote()<<error;}}}
void PlaygroundController::setMessage(const QString &message){m_message=message;emit messageChanged();}
bool PlaygroundController::configure(const QVariantMap &values){if(busy())return false;const auto config=QJsonObject::fromVariantMap(values);QString error;if(!Playground::validate(config,error)){setMessage(error);return false;}m_config=config;emit configChanged();return true;}
void PlaygroundController::useReportConfig(){if(!busy() && !m_report.isEmpty())configure(m_report["config"].toObject().toVariantMap());}
void PlaygroundController::setValue(const QString &key,const QVariant &value){if(busy())return;const QSet<QString> allowed{"name","seed","competitions","threads","athletes","focus","sampleLimit","rounds","hill"};if(!allowed.contains(key))return;m_config[key]=QJsonValue::fromVariant(value);if(key=="hill"){auto parameters=m_config["parameters"].toObject();parameters.remove("hill.k");parameters.remove("hill.hs");m_config["parameters"]=parameters;}if(key=="focus" && m_config["roster"].isArray()){const auto roster=m_config["roster"].toArray();const int focus=value.toInt();if(focus>=0 && focus<roster.size()){const auto athlete=roster[focus].toObject();auto parameters=m_config["parameters"].toObject();parameters["athlete.flightStyle"]=athlete["flight-style"];parameters["athlete.takeoff"]=athlete["takeoff-technique"];parameters["athlete.flight"]=athlete["flight-technique"];parameters["athlete.form"]=athlete["form"];parameters["athlete.landing"]=athlete["landing-style"];parameters["athlete.equality"]=athlete["jumps-equality"];m_config["parameters"]=parameters;}}if(key=="athletes"){const int count=value.toInt();m_config.remove("roster");m_config["focus"]=qMin(m_config["focus"].toInt(),qMax(0,count-1));QJsonArray rounds;for(const auto &round:m_config["rounds"].toArray())rounds.append(qMin(count,round.toInt()));m_config["rounds"]=rounds;}emit configChanged();}
void PlaygroundController::setParameter(const QString &key,double value){if(busy())return;auto parameters=m_config["parameters"].toObject();parameters[key]=value;m_config["parameters"]=parameters;emit configChanged();}
void PlaygroundController::setVariantParameter(int index,const QString &key,double value){if(busy())return;auto variants=m_config["variants"].toArray();if(index<0 || index>=variants.size())return;if(index==0){auto parameters=m_config["parameters"].toObject();parameters[key]=value;m_config["parameters"]=parameters;auto base=variants[0].toObject(),overrides=base["changes"].toObject();overrides.remove(key);base["changes"]=overrides;variants[0]=base;m_config["variants"]=variants;emit configChanged();return;}auto variant=variants[index].toObject(),changes=variant["changes"].toObject();changes[key]=value;variant["changes"]=changes;variants[index]=variant;m_config["variants"]=variants;emit configChanged();}
void PlaygroundController::renameVariant(int index,const QString &name){if(busy())return;auto variants=m_config["variants"].toArray();if(index<0 || index>=variants.size())return;auto variant=variants[index].toObject();variant["name"]=name;variants[index]=variant;m_config["variants"]=variants;emit configChanged();}
void PlaygroundController::addVariant(){if(busy())return;auto variants=m_config["variants"].toArray();if(variants.size()>=32)return;variants.append(QJsonObject{{"name",tr("Wariant %1").arg(variants.size()+1)},{"changes",QJsonObject()}});m_config["variants"]=variants;emit configChanged();}
void PlaygroundController::removeVariant(int index){if(busy() || index==0)return;auto variants=m_config["variants"].toArray();if(index<0 || index>=variants.size())return;variants.removeAt(index);m_config["variants"]=variants;emit configChanged();}
void PlaygroundController::sweep(const QString &key,double from,double to,int count){if(busy() || count<2 || count>31 || from==to)return;QJsonArray variants{QJsonObject{{"name",tr("Bazowy")},{"changes",QJsonObject()}}};bool integer=false;for(const auto &entry:Playground::parameters()){const auto p=entry.toObject();if(p["key"].toString()==key)integer=p["type"].toString()=="integer" || p["type"].toString()=="boolean";}QSet<double> used;for(int i=0;i<count;++i){double value=from+(to-from)*i/(count-1);if(integer)value=std::round(value);if(used.contains(value))continue;used.insert(value);variants.append(QJsonObject{{"name",key+" = "+QString::number(value,'g',10)},{"changes",QJsonObject{{key,value}}}});}auto next=m_config;next["variants"]=variants;QString error;if(!Playground::validate(next,error)){setMessage(error);return;}m_config=next;emit configChanged();}
void PlaygroundController::preset(const QString &name){if(busy())return;QString key="wind.mean";double from=-3,to=3;int count=7;if(name=="form"){key="athlete.form";from=40;to=100;}else if(name=="windAdvantage"){key="athlete.windBias";from=-3;to=3;}else if(name=="balance"){key="hill.balance";from=.5;to=1.5;count=5;}else if(name=="randomness"){key="engine.randomness";from=0;to=2;count=5;}else if(name=="landing"){key="athlete.landing";from=2;to=18;count=5;}sweep(key,from,to,count);}
void PlaygroundController::useAthletePack(int index){if(busy() || index<0 || index>=m_rosters.size())return;if(index==0)m_config.remove("roster");else{const auto roster=m_rosters[index]["roster"].toArray();m_config["roster"]=roster;m_config["rosterName"]=m_athletePacks[index];m_config["athletes"]=roster.size();m_config["focus"]=qMin(m_config["focus"].toInt(),int(roster.size())-1);QJsonArray rounds;for(const auto &round:m_config["rounds"].toArray())rounds.append(qMin(int(roster.size()),round.toInt()));m_config["rounds"]=rounds;auto parameters=m_config["parameters"].toObject();for(const auto &key:{"field.form","field.landing","field.equality","field.flightStyle"})parameters.remove(key);const auto focus=roster[m_config["focus"].toInt()].toObject();parameters["athlete.flightStyle"]=focus["flight-style"];parameters["athlete.takeoff"]=focus["takeoff-technique"];parameters["athlete.flight"]=focus["flight-technique"];parameters["athlete.form"]=focus["form"];parameters["athlete.landing"]=focus["landing-style"];parameters["athlete.equality"]=focus["jumps-equality"];m_config["parameters"]=parameters;}emit configChanged();}
void PlaygroundController::useHill(int index){if(busy() || index<0 || index>=m_hills.size())return;if(index==0){m_config["hill"]=Playground::example()["hill"];auto parameters=m_config["parameters"].toObject();for(const auto &entry:Playground::parameters()){const auto p=entry.toObject();if(p["group"].toString()=="hill")parameters[p["key"].toString()]=p["default"];}m_config["parameters"]=parameters;}else {const auto source=m_hills[index];m_config["hill"]=QJsonObject{{"name",source["name"]},{"k",source["k-point"]},{"hs",source["hs-point"]},{"source",source}};auto parameters=m_config["parameters"].toObject();const auto hill=Hill::getFromJson(source);parameters.remove("hill.k");parameters.remove("hill.hs");parameters["hill.balance"]=hill.getBalance();parameters["hill.distance"]=hill.getDistanceMultiplier();parameters["hill.headwindPoints"]=hill.getPointsForFrontWind();parameters["hill.tailwindPoints"]=hill.getPointsForBackWind();m_config["parameters"]=parameters;}emit configChanged();}
void PlaygroundController::useRules(int index){if(busy() || index<0 || index>=m_rules.size())return;if(index==0){m_config.remove("rulesData");auto parameters=m_config["parameters"].toObject();for(const auto &entry:Playground::parameters()){const auto p=entry.toObject();if(p["group"].toString()=="rules")parameters[p["key"].toString()]=p["default"];}m_config["parameters"]=parameters;}else {m_config["rulesData"]=m_rules[index];const auto rules=CompetitionRules::getFromJson(m_rules[index]);auto parameters=m_config["parameters"].toObject();parameters["rules.dsq"]=rules.getHasDsq()?1:0;parameters["rules.windAverage"]=rules.getWindAverageCalculatingType();parameters["rules.windDistance"]=rules.getWindCompensationDistanceEffect();parameters["rules.windCompensation"]=rules.getHasWindCompensations()?1:0;parameters["rules.gateCompensation"]=rules.getHasGateCompensations()?1:0;parameters["rules.judges"]=rules.getHasJudgesPoints()?1:0;parameters["rules.95hs"]=rules.getHas95HSRule()?1:0;m_config["parameters"]=parameters;}emit configChanged();}
void PlaygroundController::start(){if(busy())return;QString error;if(!Playground::validate(m_config,error)){setMessage(error);return;}m_control=std::make_shared<Playground::Control>();const auto config=m_config;const auto control=m_control;m_clock.start();setProperty("playgroundPendingRun",true);m_watcher.setFuture(QtConcurrent::run([config,control]{try{return Playground::run(config,control);}catch(const std::exception &error){return QJsonObject{{"error",QString::fromUtf8(error.what())}};}}));m_progress.start();setMessage(tr("Trwa eksperyment. Możesz przeglądać dotychczasowe wyniki."));emit progressChanged();}
void PlaygroundController::cancel(){if(m_control)m_control->canceled.store(true,std::memory_order_relaxed);if(busy())setMessage(tr("Przerywanie. Ukończone porównania zostaną zapisane."));}
void PlaygroundController::replay(int variant,int competition){if(busy() || m_report.isEmpty())return;const auto config=m_report["config"].toObject();const bool differentBuild=m_report["engineBuild"].toString()!=Playground::engineBuild();m_clock.start();m_replayWatcher.setFuture(QtConcurrent::run([config,variant,competition,differentBuild]{try{auto result=Playground::replay(config,variant,competition);result["differentEngineBuild"]=differentBuild;return result;}catch(const std::exception &error){return QJsonObject{{"error",QString::fromUtf8(error.what())}};}}));m_progress.start();emit progressChanged();}
void PlaygroundController::refreshHistory(){m_history.clear();QDir directory(runsDirectory());const auto folders=directory.entryList(QDir::Dirs|QDir::NoDotAndDotDot,QDir::Name|QDir::Reversed);for(const auto &folder:folders){const auto path=directory.filePath(folder+"/report.json");if(!QFile::exists(path))continue;QString error;const auto config=readObject(directory.filePath(folder+"/experiment.json"),error);auto time=QDateTime::fromString(folder,"yyyyMMdd-HHmmss-zzz");time.setTimeSpec(Qt::UTC);m_history.append(QVariantMap{{"name",config["name"].toString(folder)},{"time",time.toLocalTime().toString("dd.MM.yyyy HH:mm")},{"competitions",config["competitions"].toInt()},{"variants",config["variants"].toArray().size()},{"path",path}});}emit historyChanged();}
void PlaygroundController::loadRun(int index){if(busy() || index<0 || index>=m_history.size())return;QString error;const auto report=readObject(m_history[index].toMap()["path"].toString(),error);if(report["schema"].toInt()!=1 || !report["variants"].isArray() || !Playground::validate(report["config"].toObject(),error)){setMessage(error.isEmpty()?tr("Nieprawidłowy raport."):error);return;}m_report=report;m_reportMap=report.toVariantMap();m_replay={};m_replayMap.clear();emit reportChanged();setMessage(tr("Wczytano zapisany wynik eksperymentu."));}
void PlaygroundController::exportResults(){if(m_report.isEmpty())return;const auto root=QFileDialog::getExistingDirectory(qobject_cast<QWidget *>(parent()),tr("Folder eksportu playgroundu"));if(root.isEmpty())return;QString error;const auto path=newRunPath(root);setMessage(Playground::exportReport(m_report,path,error)?tr("Wyeksportowano do %1").arg(path):error);}
void PlaygroundController::saveConfig(){const auto path=QFileDialog::getSaveFileName(qobject_cast<QWidget *>(parent()),tr("Zapisz eksperyment"),"experiment.json","JSON (*.json)");if(path.isEmpty())return;QSaveFile file(path);const auto bytes=QJsonDocument(m_config).toJson(QJsonDocument::Indented);setMessage(file.open(QIODevice::WriteOnly) && file.write(bytes)==bytes.size() && file.commit()?tr("Zapisano konfigurację."):tr("Nie udało się zapisać konfiguracji."));}
void PlaygroundController::loadConfig(){if(busy())return;const auto path=QFileDialog::getOpenFileName(qobject_cast<QWidget *>(parent()),tr("Wczytaj eksperyment"),QString(),"JSON (*.json)");if(path.isEmpty())return;QString error;const auto config=readObject(path,error);if(!error.isEmpty() || !Playground::validate(config,error)){setMessage(error);return;}m_config=config;emit configChanged();setMessage(tr("Wczytano konfigurację eksperymentu."));}
PlaygroundWindow::PlaygroundWindow(QWidget *parent):QDialog(parent){setObjectName("simulationPlayground");setWindowTitle(tr("Playground symulacji"));setMinimumSize(360,360);resize(1280,850);auto *controller=new PlaygroundController(this);connect(controller,&PlaygroundController::progressChanged,this,[this,controller]{if(property("closeAfterPlayground").toBool() && !controller->busy())QTimer::singleShot(0,this,[this]{QDialog::reject();});});setProperty("playgroundController",QVariant::fromValue(static_cast<QObject *>(controller)));auto *layout=new QVBoxLayout(this);auto *intro=new QLabel(tr("Eksperymenty na odizolowanych kopiach danych. Konfiguracja i raport są dostępne również przez CLI."),this);intro->setWordWrap(true);layout->addWidget(intro);auto *editor=new QPlainTextEdit(QString::fromUtf8(QJsonDocument(QJsonObject::fromVariantMap(controller->config())).toJson(QJsonDocument::Indented)),this);layout->addWidget(editor);auto *run=new QPushButton(tr("Uruchom eksperyment"),this);run->setObjectName("playgroundRun");layout->addWidget(run);auto *status=new QLabel(this);status->setWordWrap(true);layout->addWidget(status);connect(run,&QPushButton::clicked,controller,[controller,editor]{const auto config=QJsonDocument::fromJson(editor->toPlainText().toUtf8());if(config.isObject() && controller->configure(config.object().toVariantMap()))controller->start();});connect(controller,&PlaygroundController::messageChanged,status,[controller,status]{status->setText(controller->message());});}

void PlaygroundWindow::reject(){auto *controller=findChild<PlaygroundController *>();if(controller && controller->busy()){setProperty("closeAfterPlayground",true);controller->cancel();return;}QDialog::reject();}
void PlaygroundWindow::closeEvent(QCloseEvent *event){auto *controller=findChild<PlaygroundController *>();if(controller && controller->busy()){setProperty("closeAfterPlayground",true);controller->cancel();event->ignore();return;}QDialog::closeEvent(event);}
